def range_compress(arr):
    if not arr:
        return []
    s = sorted(set(arr))
    result = []
    i = 0
    while i < len(s):
        j = i + 1
        while j < len(s) and s[j] == s[j - 1] + 1:
            j += 1
        if j - i == 1:
            result.append([s[i], s[i]])
        else:
            result.append([s[i], s[j - 1]])
        i = j
    return result
